<?php
 namespace Pterodactyl\Services\Dezerx\Importer; use Closure; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class Transfer { public const MODES = ['merge', 'replace', 'skip-existing']; private const MAX_FILE_BYTES = 2_147_483_648; private const DELETE_CHUNK = 100; private const REPORT_EVERY = 5; public function plan(RemoteFilesystem $client, string $source, int $maxFiles, int $maxBytes, ?Closure $onProgress = null): array { if (!$client->isDirectory($source)) { return [ 'fileMap' => [], 'files' => 0, 'bytes' => 0, 'truncated' => false, 'sample' => [], 'error' => 'There is no folder at ' . $source . ' on that host.', ]; } $walk = $client->walk($source, $maxFiles, $maxBytes, $onProgress); $paths = array_keys($walk['files']); sort($paths); return [ 'fileMap' => $walk['files'], 'files' => count($walk['files']), 'bytes' => $walk['bytes'], 'truncated' => $walk['truncated'], 'sample' => array_slice($paths, 0, 25), 'error' => null, ]; } public function emptyDestination(ServerFiles $node, string $destination): void { $this->empty($node, $this->root($destination)); } public function copyBatch( Server $server, ServerFiles $node, RemoteFilesystem $client, string $source, string $destination, string $mode, array $files, Closure $progress, ): array { $root = $this->root($destination); $writeMode = $mode === 'replace' ? 'merge' : $mode; $existing = $writeMode === 'skip-existing' ? new DestinationIndex($node, $root) : null; $made = []; $copied = 0; $skipped = 0; $failed = 0; $bytes = 0; $total = count($files); $seen = 0; foreach ($files as $path => $size) { ++$seen; $folder = dirname($path); $target = $root === '/' ? '/' . $path : $root . '/' . $path; if ($size > self::MAX_FILE_BYTES) { ++$skipped; Log::info('An import skipped a file too large to carry', [ 'server' => $server->uuid, 'path' => $path, 'size' => $size, ]); continue; } if ($existing !== null && $existing->has($folder, basename($path))) { ++$skipped; continue; } if ($folder !== '.' && !isset($made[$folder])) { $made[$folder] = true; $node->createDirectory($root === '/' ? '/' . $folder : $root . '/' . $folder); } if ($seen % self::REPORT_EVERY === 1 || $total < self::REPORT_EVERY) { $progress(sprintf('Copying %d of %d - %s', $seen, $total, $path), $seen, $total, $bytes); } if ($this->copy($client, $node, $source . '/' . $path, $target)) { ++$copied; $bytes += $size; } else { ++$failed; } } return ['copied' => $copied, 'skipped' => $skipped, 'failed' => $failed, 'bytes' => $bytes]; } private function copy(RemoteFilesystem $client, ServerFiles $node, string $remote, string $target): bool { $stream = $client->openReadStream($remote); if ($stream === false) { return false; } try { return $node->writeStream($target, $stream); } finally { if (is_resource($stream)) { fclose($stream); } } } private function empty(ServerFiles $node, string $root): void { $names = array_values(array_filter(array_map( fn (array $entry) => (string) ($entry['name'] ?? ''), $node->listFiles($root) ?? [], ))); foreach (array_chunk($names, self::DELETE_CHUNK) as $chunk) { $node->deletePaths($root, $chunk); } } public function root(string $destination): string { $path = '/' . trim(str_replace('\\', '/', $destination), '/'); return $path === '/' || str_contains($path, '..') ? '/' : rtrim($path, '/'); } } 